import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { parseWranglerConfig, publishedDir, wranglerConfigPath } from '../lib.mjs';

// WHY. Workers static assets serves a request for a `.html` path by 307-redirecting
// it to the extensionless URL the asset actually lives at, so a page that still
// links to the `.html` form keeps working — but costs every visitor who follows it
// an extra round trip they'd never see if the link named the served path directly.
//
// SCOPE. The published tree's own `.html` files, and only a link that plainly
// targets another one of them: a relative href ending `.html`, never an absolute
// URL or a `mailto:` — an external site's own `.html` page is its redirect to
// diagnose, not this repo's.

const INTERNAL_HTML_HREF = /href=["'](?!https?:\/\/|mailto:)([^"']*\.html)["']/gi;

