import { ruleTester } from '../../../../engine-tests/helpers.mjs';
import internalLinksOmitHtmlExtension from '../../worldRules/internal-links-omit-html-extension.mjs';

const config = (obj) => `${JSON.stringify(obj, null, 2)}\n`;
const sound = { assets: { directory: './site' } };

ruleTester(internalLinksOmitHtmlExtension, {
  clean: {
    'no wrangler config at all': {
      files: { 'site/index.html': '<a href="/about">About</a>' },
    },
    'a link already extensionless': {
      files: { 'wrangler.json': config(sound), 'site/index.html': '<a href="/about">About</a>' },
    },
    'an external link that happens to end in .html': {
      files: { 'wrangler.json': config(sound), 'site/index.html': '<a href="https://example.com/x.html">X</a>' },
    },
    'a mailto link': {
      files: { 'wrangler.json': config(sound), 'site/index.html': '<a href="mailto:x@example.com">x</a>' },
    },
    'a .html file outside the published tree': {
      files: { 'wrangler.json': config(sound), 'docs/notes.html': '<a href="/about.html">About</a>' },
    },
  },
  flagged: {
    'a relative internal link still naming the .html file': {
      files: { 'wrangler.json': config(sound), 'site/index.html': '<a href="/about.html">About</a>' },
      at: [{ file: 'site/index.html', line: 1, what: /about\.html/, fix: /drop the \.html suffix/ }],
    },
    'a bare filename link, reported at its own line': {
      files: { 'wrangler.json': config(sound), 'site/index.html': '<p>x</p>\n<a href="privacy.html">Privacy</a>\n' },
      at: [{ file: 'site/index.html', line: 2, what: /privacy\.html/ }],
    },
  },
});

